INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-teatro-de-sombras-nocturnas', 'El Teatro de Sombras Nocturnas', 'Dinámica de dramatización con siluetas y contraluz donde los scouts representan leyendas scouts tras una pantalla iluminada.', '<h2>📜 Descripción de El Teatro de Sombras Nocturnas</h2>
<p><b>El Teatro de Sombras Nocturnas</b> es una actividad dramática y cooperativa de contraluz diseñada para realizarse al anochecer o durante una fogata de campamento. El escenario consiste en una gran sábana blanca tensada verticalmente entre dos árboles o pilares, tras la cual se coloca una fuente de luz potente (como una linterna LED o foco de campamento). Las patrullas o seisenas se ubican ocultas detrás del telón e interpretan obras cortas proyectando siluetas recortadas en cartulina, sus propias manos o sombras corporales sobre la tela estirada.</p>
<p>Los espectadores, sentados frente al telón iluminado, observan únicamente las sombras oscuras que cobran vida en movimiento mientras un narrador o la misma patrulla relata una leyenda scout, una aventura en la naturaleza o una vivencia del grupo (ej. <i>''El primer campamento scout en Brownsea''</i>, <i>''La Leyenda de Tangata Manu''</i> o <i>''El Rescate en la Selva''</i>). Manipulando la distancia entre las figuras y la linterna, los scouts aprenden a jugar con la óptica: acercar una silueta a la luz la vuelve gigante ante el público, mientras que pegarla a la sábana la define con nitidez absoluta.</p>
<p>Esta dinámica fomenta la creatividad escénica, la superación del miedo al escenario tras el velo del telón, el trabajo en equipo y la contención afectiva en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega El Teatro de Sombras Nocturnas?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y entusiasmo, los dirigentes y guías deben seguir estos pasos:</p>
<ul>
  <li><b>Montaje de la Pantalla en Penumbra:</b> Se tensa firmemente una sábana blanca sin arrugas entre dos árboles o postes. La linterna se ubica a 2 metros detrás del centro del telón apuntando hacia el público.</li>
  <li><b>Diseño de Guion y Siluetas:</b> Cada patrulla elige una leyenda o historia scout y recorta en cartulina negra las figuras principales (árboles, animales, scouts, carpas), pegándolas en palitos de madera.</li>
  <li><b>Distribución de Roles de Patrulla:</b> El equipo designa a los titiriteros (quienes mueven las siluetas), al operador de luz (quien enfoca y genera efectos de iluminación) y al narrador o sonidista (quien relata y realiza efectos de sonido con la voz o elementos naturales).</li>
  <li><b>Ensayo de Escalas y Movimiento:</b> Se practica el movimiento de las siluetas: pegadas a la tela para trazos nítidos y alejadas hacia la luz para sombras gigantes de misterio.</li>
  <li><b>Función de Fogata y Aplausos:</b> Apagadas las luces del entorno, cada patrulla presenta su obra de 3 a 5 minutos. Al concluir, el grupo completo sale al frente de la pantalla para recibir el tradicional aplauso Scout.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Teatro de Sombras Nocturnas</h2>
<p>La actividad valora la expresividad, el uso del contraluz y la mística en el Tally:</p>
<ul>
  <li><b>Mayor Dominio de la Óptica de Sombras:</b> Otorgar 5 puntos a la patrulla que altere mejor las escalas (gigantes y miniaturas) con fluidez.</li>
  <li><b>Mística y Narración Escénica:</b> Otorgar 3 puntos al equipo cuya historia y efectos de sonido transmitan la mística scout con mayor emoción.</li>
  <li><b>Trabajo Cooperativo de Bastidores:</b> Otorgar 3 puntos a la unidad que opere entre telones sin interrupciones ni baches de luz.</li>
</ul>', '/uploads/el-teatro-de-sombras-nocturnas.webp', 'publicado', '{"areas": ["creatividad", "afectividad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Sábana Blanca", "Linterna", "Cartulinas"], "objetivos": ["Fomentar la comunicación e interpretación", "Perder el miedo a la oscuridad", "Estimular la creatividad", "Crear un clima de pertenencia"], "justificacion_areas": "El Teatro de Sombras Nocturnas potencia la creatividad al exigir la conceptualización del espacio bidimensional a través del contraluz y la manipulación de escalas ópticas. Desarrolla la afectividad al construir un clima cálido de confianza, superación del miedo a la oscuridad y pertenencia fraterna en fogata desde Manada hasta Clan.", "variaciones": "<b>Sombras de Manos Kinésicas:</b> Realizar la representación utilizando exclusivamente sombras formadas con las manos.<br><b>Filtros de Colores:</b> Colocar papel celofán de colores sobre las linternas para dar ambientación cromática.<br><b>Teatro Mudo con Sonido Ambiental:</b> Representar la escena sin palabras, solo con efectos de sonido naturales.", "recomendaciones": "Probar la intensidad de las linternas antes de la presentación. Promover el silencio respetuoso durante las funciones.", "objetivos_educativos": [{"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Preparando las figuras de sombras y actuando detrás de la pantalla."}, {"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Compartiendo un clima de calidez y confianza fraterna en la penumbra de fogata."}, {"id": "897408de-c314-4908-aee0-4a0e0e56d4ba", "area": "Creatividad", "unidad": "Manada", "texto": "Converso con los demás sobre las cosas que me llaman la atención.", "como_se_cumple": "Comentando con entusiasmo los efectos de sombras logrados con la linterna."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Respetando las interpretaciones y voces de los lobatos detrás del telón."}, {"id": "0d742d23-ebe1-40e6-97df-37bc03edb010", "area": "Creatividad", "unidad": "Compañía", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "como_se_cumple": "Expresando relatos e historias scouts en la obra de sombras."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Coordinando los movimientos de siluetas con las voces de las pares."}, {"id": "0136350b-c2b2-429f-8feb-2fdc57e29b8b", "area": "Creatividad", "unidad": "Compañía", "texto": "Me gusta actuar y expresarme.", "como_se_cumple": "Representando leyendas y dramatizaciones en la velada nocturna."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Creando un ambiente afectivo de contención e integración artística."}, {"id": "981fa19b-7f60-4e0e-b2fa-16123df5e37e", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "como_se_cumple": "Diseñando guiones y siluetas para las funciones de la Tropa."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Escuchando con atención y valoración las voces de las patrullas."}, {"id": "9758e4f9-728b-4435-a8a3-11fd36c5e3be", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Demostrando destreza manual en el manejo de bastidores e iluminación."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Afianzando la mística y la fraternidad de la patrulla mediante el teatro."}, {"id": "ed17d59c-1c64-4080-a206-bbe72eeae5a4", "area": "Creatividad", "unidad": "Avanzada", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Liderando representaciones místicas y climas gratos de fogata en Avanzada."}, {"id": "3b32ea2c-da58-487c-bea4-e02f301f5e3e", "area": "Afectividad", "unidad": "Avanzada", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Fomentando espacios de encuentro afectivo y desinhibición sin prejuicios."}, {"id": "ef75fbed-4a6d-49ea-bfab-f2952415e1a0", "area": "Creatividad", "unidad": "Clan", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Innovando en técnicas de iluminación y dramatización en el Clan Rover."}, {"id": "d0ba748f-313b-4ffe-b2a3-fb21c1f8943f", "area": "Afectividad", "unidad": "Clan", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Promoviendo la hermandad alegre y el clima de pertenencia en el Clan."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

